    28→  const values: unknown[] = [];
    29→  let idx = 1;
    30→  for (const [key, value] of Object.entries(input)) {
    31→    fields.push(`${key} = $${idx}`);
    32→    values.push(value);
    33→    idx++;
    34→  }
